# Settings for running an experiment on HPC Vega (SLURM). Sourced by every
# script in hpc/vega/.
#
# Do not edit this file on the cluster: a run refuses to start from
# uncommitted code (provenance.py). Put local values -- your account above
# all -- in hpc/vega/config.local.sh, which git ignores, or in the
# environment. Anything set there wins over the defaults below.

HERE_VEGA="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO="$(cd "$HERE_VEGA/../.." && pwd)"
[ -f "$HERE_VEGA/config.local.sh" ] && . "$HERE_VEGA/config.local.sh"

# --- SLURM -------------------------------------------------------------------
# Project account to charge (sbatch --account). Empty: none is passed.
: "${ACCOUNT:=}"
# Vega's CPU partition. Jobs are capped at 6 h by the experiment, under its
# limit.
: "${PARTITION:=cpu}"
# Cores per job: the random forest fits its 100 trees on these, and
# NSGAII-MIIP computes its mutual-information matrix on them.
: "${CPUS:=8}"
# Memory per job. NSGAII-MIIP's pairwise MI matrix on Heartbeat (24,705
# features) alone is about 5 GB.
: "${MEM:=32G}"
# At most this many array tasks at once (sbatch --array=...%N).
: "${MAX_PARALLEL:=200}"
# Array tasks per sbatch call; Vega's MaxArraySize may be below the job count.
: "${ARRAY_CHUNK:=1000}"

# --- software ------------------------------------------------------------------
# Python environment, built by setup.sh (Miniforge, git-ignored).
: "${ENV_DIR:=$REPO/.hpc/env}"
: "${MINIFORGE_DIR:=$REPO/.hpc/miniforge}"
: "${PYTHON_VERSION:=3.11}"
# The FASTENER clone the experiments ran with (DEC-40, DEC-41).
: "${FASTENER_URL:=https://github.com/klemenkenda/FASTENER}"
: "${FASTENER_COMMIT:=3be5697}"

PY="$ENV_DIR/bin/python"
